'use strict';
const main=document.getElementById('main'),dialog=document.getElementById('flow-dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const labels={available:'Available',requested:'Requested',held:'Held',booked:'Booked'};
let backend,selected='B09',view='event',refreshTimer,busy=false,draft=null,editId=null,availableOnly=false,zoneFilter='',requestDraft=null;
function notify(text){document.getElementById('trial-status').textContent=text;}
function panel(title,text){main.innerHTML=`<section class="intro"><div><div class="eyebrow">STALLSLOT / PRIVATE TRIAL</div><h1>${title}</h1><p class="admin-note">${text}</p></div></section>`;}
function showLogin(message='Sign in with the account provided for your trial.'){clearInterval(refreshTimer);document.getElementById('role-label').textContent='Private workspace';document.getElementById('account-actions').hidden=true;panel('Your market. <em>Your workspace.</em>',esc(message));main.insertAdjacentHTML('beforeend',`<form id="login-form" class="ticket login-card"><div class="ticket-body"><h2>Welcome back.</h2><label class="field"><span>Email</span><input type="email" name="email" autocomplete="username" required></label><label class="field"><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label><p class="form-error" id="login-error" role="alert"></p><button class="primary">Sign in ↗</button><p class="fine">Invitation only. Need access or a password reset? Contact Krishna through your existing email conversation.</p></div></form>`);document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const {error}=await backend.client.auth.signInWithPassword({email:e.target.email.value.trim(),password:e.target.password.value});if(error)throw Error('Sign-in failed. Check your email and password.');await startSession();}catch(err){document.getElementById('login-error').textContent=err.message;}finally{b.disabled=false;}};}
async function startSession(){try{await backend.load();document.getElementById('account-actions').hidden=false;view=backend.role()==='organiser'?'admin':'event';render();clearInterval(refreshTimer);refreshTimer=setInterval(()=>sync(),20000);}catch(err){panel('Access needed.',esc(err.message));main.insertAdjacentHTML('beforeend','<button class="small-button" id="try-login">Use another account</button>');document.getElementById('try-login').onclick=async()=>{await backend.client.auth.signOut({scope:'local'});showLogin();};}}
async function sync(){if(busy||dialog.open||document.hidden||view==='layout')return;try{await backend.refresh();render();notify('Availability updated.');}catch{notify('Could not refresh. Check your connection before making changes.');}}
function position(s){return [s.x,s.y];}
function render(){
 const e=backend.event(),organiser=backend.role()==='organiser';
 if(!backend.list().some(s=>s.id===selected))selected=backend.list()[0]?.id;
 document.getElementById('trial-mode').textContent=e.is_test?'PRIVATE PRACTICE EVENT · NO REAL PAYMENTS':'PRIVATE EVENT · ORGANISER APPROVAL REQUIRED';
 document.getElementById('role-label').textContent=organiser?'Organiser account':'Vendor account';
 for(const [id,page,visible] of [['event','event',true],['map','vendor',true],['booking','booking',!organiser],['organiser','admin',organiser],['layout','layout',organiser]]){
  const b=document.getElementById(id+'-button');b.hidden=!visible;b.classList.toggle('active',view===page);
  if(view===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');
 }
 if(view==='layout'&&organiser)renderLayout();else if(view==='admin'&&organiser)renderAdmin();else if(view==='event')renderEvent();else if(view==='booking')renderBooking();else renderMap();
}
function renderMap(){
 const all=backend.list(),s=all.find(x=>x.id===selected),own=all.find(x=>x.mine),e=backend.event();
 const canRequest=s&&backend.role()==='vendor'&&e.is_open&&!own&&s.status==='available';
 const zones=[...new Set(all.map(x=>x.zone))];
 if(zoneFilter&&!zones.includes(zoneFilter))zoneFilter='';
 main.innerHTML=steps(2)+`<div class="page-heading"><div><div class="eyebrow">${esc(e.name)}</div><h1>Choose your stall.</h1><p>${e.is_open?'Select a space to see its price and details.':'Requests are closed. You can still explore the layout.'}</p></div><button class="small-button" data-go="event">← Event details</button></div>
 <div class="workspace"><section aria-label="Stall map"><div class="map-card"><div class="map-toolbar"><strong>${all.filter(x=>x.status==='available').length} / ${all.length} available</strong><button class="small-button" id="refresh-map">Refresh</button></div>
 <div class="map-filters"><label>Zone <select id="zone-filter"><option value="">All zones</option>${zones.map(z=>`<option ${zoneFilter===z?'selected':''}>${esc(z)}</option>`).join('')}</select></label><label><input type="checkbox" id="available-filter" ${availableOnly?'checked':''}> Available only</label></div>
 <div class="map-scroll" tabindex="0" aria-label="Scrollable venue map">${mapMarkup(all,selected)}</div><div class="map-bottom"><div class="legend">${Object.keys(labels).map(k=>`<span><i class="swatch ${k}" aria-hidden="true"></i>${labels[k]}</span>`).join('')}<span><i class="swatch chosen"></i>Selected</span></div><p class="fine">Schematic layout · Check each stall’s listed dimensions. Scroll the map to explore.</p></div></div></section>
 <aside class="selection-panel">${s?`<article class="ticket"><div class="ticket-head"><div class="eyebrow">Your selection</div><div class="ticket-identity"><span class="ticket-number">${esc(s.id)}</span><span class="ticket-status">${labels[s.status]}</span></div></div><div class="ticket-body"><h2>${esc(s.zone)}</h2><dl class="details-grid"><div><dt>Stall size</dt><dd>${esc(s.size)}</dd></div><div><dt>Electricity</dt><dd>${s.power?'Included':'Not included'}</dd></div><div><dt>Suitable for</dt><dd>${typeLabel(s.stall_type)}</dd></div></dl><div class="price-row"><strong>${money(s.price)}</strong><span>total stall price</span></div><p class="fine">50% deposit: ${money(s.price/2)} after approval. ${e.is_test?'Simulation only.':''}</p><button class="primary" id="request-button" ${canRequest?'':'disabled'}>Continue with ${esc(s.id)} →</button><p class="fine">${backend.role()==='organiser'?'Vendor accounts submit requests.':own?'You already have a booking request for this event.':!e.is_open?'The organiser has closed requests.':'Selecting a stall does not reserve it. Approval is required.'}</p>${own?'<button class="small-button" data-go="booking">View my booking →</button>':''}</div></article>`:'<p>No stalls have been added.</p>'}</aside></div>`;
 wireGo();
 main.querySelectorAll('[data-stall]').forEach(b=>b.onclick=()=>{selected=b.dataset.stall;renderMap();main.querySelector('[data-stall="'+selected+'"]').focus();});
 if(s)document.getElementById('request-button').onclick=()=>requestDialog(s);
 document.getElementById('refresh-map').onclick=sync;
 document.getElementById('zone-filter').onchange=e=>{zoneFilter=e.target.value;renderMap();document.getElementById('zone-filter').focus();};
 document.getElementById('available-filter').onchange=e=>{availableOnly=e.target.checked;renderMap();document.getElementById('available-filter').focus();};
}
function modal(title,body){document.getElementById('dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="close" id="close-dialog" aria-label="Close dialog">×</button></div>${body}</div>`;document.getElementById('close-dialog').onclick=()=>{if(!busy)dialog.close();};if(!dialog.open)dialog.showModal();}
async function submit(form,work,success){if(busy)return;busy=true;form.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);try{const savedMessage=await work();dialog.close();render();notify(savedMessage||success);}catch(err){form.querySelector('[role="alert"]').textContent=err.message||'Could not save. Refresh and check your request before trying again.';try{await backend.refresh();}catch{} }finally{busy=false;form.querySelectorAll('button,input,select').forEach(x=>x.disabled=false);}}
function requestDialog(s,values={}){
 const categories=s.stall_type==='food'?['Food & drink']:s.stall_type==='retail'?['Fashion','Accessories','Art & craft','Home & lifestyle']:['Fashion','Accessories','Art & craft','Home & lifestyle','Food & drink'];
 const revision=backend.event().layout_revision;
 modal('Your business details',`<p class="dialog-sub">Stall ${esc(s.id)} · ${money(s.price)}. ${backend.event().is_test?'Use fictional names for this practice event.':''}</p><form id="request-form"><label class="field"><span>Contact name</span><input name="name" required minlength="2" maxlength="60" autocomplete="name" value="${esc(values.name||'')}"></label><label class="field"><span>Business name</span><input name="business" required minlength="2" maxlength="80" autocomplete="organization" value="${esc(values.business||'')}"></label><label class="field"><span>What do you sell?</span><select name="category">${categories.map(c=>`<option ${values.category===c?'selected':''}>${c}</option>`).join('')}</select></label><p class="fine">These details are shared with your organiser. Other vendors see availability only.</p><p class="form-error" role="alert"></p><button class="primary">Review request →</button></form>`);
 document.getElementById('request-form').onsubmit=e=>{e.preventDefault();requestDraft={s,data:Object.fromEntries(new FormData(e.target)),revision};reviewRequest();};
}
function renderAdmin(){const rows=backend.list().filter(s=>s.status!=='available');main.innerHTML=`<section class="intro"><div><div class="eyebrow">${esc(backend.event().name)} / ORGANISER</div><h1>Good markets. <em>Less admin.</em></h1><p class="admin-note">Review vendors, hold spaces, and record deposits you have checked. Changes are saved for this event.</p></div></section><section class="admin-panel"><div class="panel-head"><h2>Requests & bookings</h2><button class="small-button" id="refresh-admin">Refresh</button></div><div class="table-scroll"><table><thead><tr><th>Vendor</th><th>Stall</th><th>Status</th><th>Next step</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.business)}</strong><small>${esc(s.name)} · ${esc(s.category)}</small></td><td>${s.id}</td><td><span class="pill ${s.status}">${labels[s.status]}</span></td><td><div class="row-actions">${s.status==='requested'?`<button class="small-button emphasis" data-action="approve" data-id="${s.id}">Approve</button>`:s.status==='held'?`<button class="small-button emphasis" data-action="confirm" data-id="${s.id}">Check deposit</button>`:'Deposit recorded'}${['requested','held'].includes(s.status)?`<button class="small-button" data-action="release" data-id="${s.id}">${s.status==='requested'?'Decline':'Release'}</button>`:''}</div></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No requests yet. Invite a vendor to try the map.</div>'}</div></section>`;document.getElementById('refresh-admin').onclick=sync;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionDialog(b.dataset.id,b.dataset.action));}
function actionDialog(id,action){const s=backend.get(id),isTest=backend.event().is_test;modal(action==='approve'?'Approve this request?':action==='release'?'Release this space?':'Check the deposit.',`<p class="dialog-sub">${esc(s.business)} · stall ${id}</p><form id="action-form">${action==='confirm'?`<p>Expected deposit: <strong>${money(s.price/2)}</strong></p><label class="check-label"><input name="verified" type="checkbox" required><span>${isTest?'Simulate checking':'I have checked my bank or payment app and verified receipt of'} the ${money(s.price/2)} deposit.</span></label><p class="fine">${isTest?'Practice event. Do not send real money.':'StallSlot records your confirmation. It does not move money or verify payment automatically.'}</p>`:`<p>${action==='approve'?'The stall stays held for this vendor until you record the deposit.':'This frees the stall. The previous request remains in the event record. No email is sent.'}</p>`}<p class="form-error" role="alert"></p><button class="primary">${action==='approve'?'Approve & hold':action==='release'?'Release stall':'Confirm booking'} ↗</button></form>`);document.getElementById('action-form').onsubmit=e=>{e.preventDefault();const verified=e.target.elements.verified?.checked===true;submit(e.target,async()=>{const fresh=await backend.change(id,action,verified);if(!fresh)return 'Change saved. Refresh to see the latest status.';},'Change saved.');};}

function typeLabel(type){return {retail:'Brands & retail',food:'Food & drink',any:'All categories'}[type]||'All categories';}
function steps(active){return '<ol class="booking-steps" aria-label="Booking steps">'+['Event details','Choose stall','Review request','Booking status'].map((s,i)=>'<li '+(i+1===active?'aria-current="step"':'')+'><span>'+(i+1)+'</span>'+s+'</li>').join('')+'</ol>';}
function navigate(page){
 if(busy)return;
 if(draft&&view==='layout'&&page!=='layout'){
  modal('Leave your layout draft?','<p>Your unsaved edits will be discarded.</p><div class="row-actions"><button class="small-button" id="keep-editing">Keep editing</button><button class="primary" id="leave-editor">Discard & leave</button></div>');
  document.getElementById('keep-editing').onclick=()=>dialog.close();
  document.getElementById('leave-editor').onclick=()=>{draft=null;dialog.close();view=page;render();};return;
 }
 view=page;render();window.scrollTo({top:0,behavior:'smooth'});
}
function wireGo(){main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));}
function mapMarkup(stalls,choice,editor=false){
 return '<div class="venue-canvas" role="group" aria-label="'+(editor?'Layout preview':'Interactive stall map')+'"><span class="venue-caption">VENUE MAP · NOT TO SCALE</span>'+stalls.map(s=>{
  const dim=!editor&&((availableOnly&&s.status!=='available')||(zoneFilter&&zoneFilter!==s.zone));
  return '<button class="space '+(s.status||'available')+' '+(s.id===choice?'selected':'')+' '+(dim?'dimmed':'')+'" style="left:'+Number(s.x)+'%;top:'+Number(s.y)+'%" '+(editor?'data-edit':'data-stall')+'="'+esc(s.id)+'" aria-label="Stall '+esc(s.id)+', '+(labels[s.status]||'Available')+'" aria-pressed="'+(s.id===choice)+'"><strong>'+esc(s.id)+'</strong><small>'+(editor&&s.locked?'Locked':s.status==='available'||editor?money(s.price):labels[s.status])+'</small></button>';
 }).join('')+'</div>';
}
function renderEvent(){
 const e=backend.event(),all=backend.list(),own=all.find(s=>s.mine),prices=all.map(s=>s.price);
 main.innerHTML=steps(1)+`<section class="event-overview"><div class="event-art" aria-hidden="true"><div class="market-mark">${all.slice(0,36).map((s,i)=>`<span class="${s.status==='booked'?'occupied':''}" style="--i:${i}">${esc(s.id)}</span>`).join('')}</div><span class="art-caption">A SPACE FOR YOUR NEXT CHAPTER.</span></div><div class="event-copy"><span class="event-tag">${e.is_test?'Practice market':'Private market'}</span><h1>${esc(e.name)}</h1><p class="event-description">${esc(e.description)}</p><dl class="event-facts"><div><dt>Venue</dt><dd>${esc(e.venue)}</dd></div><div><dt>Date</dt><dd>${e.event_date?new Date(e.event_date+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'}):'To be announced'}</dd></div><div><dt>Stalls</dt><dd>${all.length} spaces · ${all.filter(s=>s.status==='available').length} available</dd></div><div><dt>Starting at</dt><dd>${prices.length?money(Math.min(...prices)):'Not set'} / stall</dd></div></dl><div class="event-cta"><button class="primary" data-go="${own?'booking':'vendor'}">${own?'View my booking':'Choose a stall'} →</button><span>${e.is_open?'Requests open':'Requests closed · View the layout'}</span></div></div></section><section class="how-booking"><h2>Know what happens next.</h2><div><article><b>01 / Pick your space</b><p>Compare the location, size and total price on the venue map.</p></article><article><b>02 / Send a request</b><p>Share your business details. The organiser reviews your request.</p></article><article><b>03 / Get confirmed</b><p>After approval, the organiser checks the deposit and confirms the stall. ${e.is_test?'This event uses simulated deposits.':''}</p></article></div></section>`;
 wireGo();
}
function renderBooking(){
 const s=backend.list().find(s=>s.mine),e=backend.event();
 main.innerHTML=steps(4)+`<div class="page-heading"><div><div class="eyebrow">YOUR EVENT WORKSPACE</div><h1>My booking.</h1><p>One place for your stall and its latest status.</p></div><button class="small-button" id="refresh-booking">Refresh status</button></div>`+(s?`<section class="booking-pass"><div class="pass-identity"><span class="event-tag">${labels[s.status]}</span><h2>${esc(e.name)}</h2><strong class="pass-stall">${esc(s.id)}</strong><p>${esc(s.zone)} · ${esc(s.size)}</p></div><div class="pass-details"><h2>${s.status==='booked'?'Your stall is confirmed.':s.status==='held'?'Approved. Deposit review is next.':'Request sent. Awaiting review.'}</h2><p>${esc(s.business)} · ${esc(s.category)}</p><ol class="status-timeline">${[['requested','Request saved'],['held','Organiser approval'],['booked','Deposit recorded · Booked']].map(([status,label],i)=>`<li class="${['requested','held','booked'].indexOf(s.status)>=i?'done':''}">${label}</li>`).join('')}</ol><dl class="event-facts"><div><dt>Total stall price</dt><dd>${money(s.price)}</dd></div><div><dt>Deposit ${s.depositVerified?'recorded':'after approval'}</dt><dd>${money(s.price/2)}</dd></div></dl><p class="fine">${e.is_test?'Practice booking. No money is collected.':'Contact your organiser through your existing conversation for payment instructions.'}</p><p class="reference">Reference ${esc(s.bookingId)}</p><button class="small-button" id="see-stall">See my stall on the map →</button></div></section>`:`<section class="empty-state"><h2>Your next market starts here.</h2><p>You have no booking request for this event yet.</p><button class="primary" data-go="vendor">Explore the stall map →</button></section>`);
 wireGo();document.getElementById('refresh-booking').onclick=sync;
 if(s)document.getElementById('see-stall').onclick=()=>{selected=s.id;navigate('vendor');};
}
function reviewRequest(){
 const {s,data,revision}=requestDraft;
 modal('Review your request',`<p class="dialog-sub">Check the details before sending. This is a request, not an instant booking.</p><dl class="review-list"><div><dt>Event</dt><dd>${esc(backend.event().name)}</dd></div><div><dt>Stall</dt><dd>${esc(s.id)} · ${esc(s.zone)} · ${esc(s.size)}</dd></div><div><dt>Business</dt><dd>${esc(data.business)} · ${esc(data.category)}</dd></div><div><dt>Total price</dt><dd>${money(s.price)}</dd></div><div><dt>Deposit after approval</dt><dd>${money(s.price/2)}</dd></div><div><dt>Due now</dt><dd>₹0</dd></div></dl><form id="review-form"><p class="fine">${backend.event().is_test?'Practice request. No real payments.':'Your organiser must approve and verify the deposit before the stall is confirmed.'}</p><p class="form-error" role="alert"></p><div class="row-actions"><button type="button" class="small-button" id="edit-request">Edit details</button><button class="primary">Send request →</button></div></form>`);
 document.getElementById('edit-request').onclick=()=>requestDialog(s,data);
 document.getElementById('review-form').onsubmit=e=>{e.preventDefault();submit(e.target,async()=>{const result=await backend.request(s.id,data,revision);view='booking';requestDraft=null;return result.refreshPending?'Request saved. Refresh to see the latest status.':'Request sent. Track organiser approval here.';},'Request saved.');};
}
function layoutFields(s){return ['id','price','x','y','width_ft','depth_ft','power','zone','stall_type'].reduce((o,k)=>(o[k]=s[k],o),{});}


function renderLayout(){
 const e=backend.event();
 if(!draft){draft={details:{name:e.name,venue:e.venue,event_date:e.event_date||'',description:e.description},stalls:backend.list().map(s=>({...layoutFields(s),locked:s.locked})),revision:e.layout_revision};editId=draft.stalls[0]?.id;}
 const s=draft.stalls.find(s=>s.id===editId)||draft.stalls[0];editId=s?.id;
 main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">ORGANISER / LAYOUT STUDIO</div><h1>Your venue. Your layout.</h1><p>${e.is_open?'Requests are open. Close them before saving layout changes.':'Edit your draft, preview the map, then save it for your invited vendors.'}</p></div><span class="event-tag">${draft.stalls.length} / 100 stalls</span></div><div class="layout-studio"><section><details class="event-settings"><summary>Event details</summary><div class="form-grid">${[['name','Event name'],['venue','Venue'],['event_date','Event date']].map(([k,label])=>`<label class="field"><span>${label}</span><input data-detail="${k}" type="${k==='event_date'?'date':'text'}" value="${esc(draft.details[k])}" ${k==='event_date'?'':`maxlength="${k==='name'?100:160}" required`}></label>`).join('')}<label class="field"><span>About this event</span><textarea data-detail="description" maxlength="1000">${esc(draft.details.description)}</textarea></label></div></details><div class="map-card"><div class="map-toolbar"><strong>Layout preview</strong><span class="fine">Select a stall to edit</span></div><div class="map-scroll" tabindex="0" aria-label="Scrollable layout preview">${mapMarkup(draft.stalls,editId,true)}</div></div><div class="editor-tools"><button class="small-button" id="add-stall">+ Add stall</button><button class="small-button" id="grid-layout" ${draft.stalls.some(s=>s.locked)?'disabled':''}>Create a grid…</button><p class="fine">Grid replaces an unbooked layout. Positions use a 0–92 grid; leave at least 8 units between stalls. The plan is schematic, not a safety or capacity assessment.</p></div></section><aside class="editor-panel"><h2>${s?'Stall '+esc(s.id):'Add your first stall'}</h2>${s?`<p class="fine">${s.locked?'Locked: this stall has booking history.':'Edit the details and use X / Y to position this stall.'}</p><form id="stall-editor"><fieldset ${s.locked?'disabled':''}><div class="form-grid">${[['price','Price (₹)',1,1000000],['width_ft','Width (ft)',1,100],['depth_ft','Depth (ft)',1,100],['x','X position',0,92],['y','Y position',0,92]].map(([k,label,min,max])=>`<label class="field"><span>${label}</span><input name="${k}" type="number" min="${min}" max="${max}" step="1" value="${s[k]}" required></label>`).join('')}<label class="field"><span>Zone</span><input name="zone" maxlength="60" required value="${esc(s.zone)}"></label><label class="field"><span>Allowed vendors</span><select name="stall_type">${['retail','food','any'].map(k=>`<option value="${k}" ${s.stall_type===k?'selected':''}>${typeLabel(k)}</option>`).join('')}</select></label><label class="check-label"><input name="power" type="checkbox" ${s.power?'checked':''}> Electricity included</label></div><p class="form-error" role="alert"></p><button class="small-button" type="submit">Apply to preview</button><button class="small-button danger" type="button" id="remove-stall" ${draft.stalls.length===1?'disabled':''}>Remove stall</button></fieldset></form>`:''}<div class="save-layout"><p id="layout-error" class="form-error" role="alert"></p><button class="primary" id="save-layout" ${e.is_open?'disabled':''}>Save layout for vendors →</button><button class="small-button" id="discard-layout">Reload saved layout</button><p class="fine">Draft changes reach vendors only after saving. Existing bookings stay protected.</p></div></aside></div>`;
 main.querySelectorAll('[data-detail]').forEach(input=>input.oninput=()=>draft.details[input.dataset.detail]=input.value);
 main.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{if(captureStall()){editId=b.dataset.edit;renderLayout();}});
 if(s){document.getElementById('stall-editor').onsubmit=ev=>{ev.preventDefault();if(captureStall())renderLayout();};document.getElementById('remove-stall').onclick=()=>{if(s.locked||draft.stalls.length===1)return;draft.stalls=draft.stalls.filter(x=>x.id!==s.id);editId=draft.stalls[0]?.id;renderLayout();};}
 document.getElementById('add-stall').onclick=()=>{
  if(!captureStall())return;if(draft.stalls.length>=100){notify('This version supports up to 100 stalls per layout.');return;}
  let point;for(let y=2;y<=92&&!point;y+=10)for(let x=2;x<=92;x+=10)if(!draft.stalls.some(s=>Math.abs(s.x-x)<8&&Math.abs(s.y-y)<8)){point={x,y};break;}
  if(!point){notify('Make room on the map before adding another stall.');return;}
  let n=1;while(draft.stalls.some(s=>s.id==='S'+String(n).padStart(2,'0')))n++;
  const id='S'+String(n).padStart(2,'0');draft.stalls.push({id,price:3500,...point,width_ft:8,depth_ft:8,power:false,zone:'Main area',stall_type:'retail',locked:false});editId=id;renderLayout();
 };
 document.getElementById('grid-layout').onclick=()=>{
  if(!captureStall())return;
  modal('Create a stall grid',`<p>This replaces your unsaved layout draft. No booking records are removed.</p><form id="grid-form"><label class="field"><span>Number of stalls</span><input type="number" name="count" min="1" max="100" value="30" required></label><label class="field"><span>Columns</span><input type="number" name="columns" min="1" max="10" value="6" required></label><p class="form-error" role="alert"></p><button class="primary">Create preview</button></form>`);
  document.getElementById('grid-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),count=Number(f.get('count')),cols=Number(f.get('columns'));if(Math.ceil(count/cols)>10){ev.target.querySelector('[role="alert"]').textContent='Use more columns to keep the grid within 10 rows.';return;}draft.stalls=Array.from({length:count},(_,i)=>({id:'S'+String(i+1).padStart(2,'0'),price:3500,x:2+(i%cols)*10,y:2+Math.floor(i/cols)*10,width_ft:8,depth_ft:8,power:false,zone:'Main area',stall_type:'retail',locked:false}));editId=draft.stalls[0].id;dialog.close();renderLayout();};
 };
 document.getElementById('discard-layout').onclick=async()=>{if(busy)return;busy=true;try{await backend.refresh();draft=null;renderLayout();notify('Saved layout loaded.');}catch{notify('Could not load the saved layout. Your draft is still here.');}finally{busy=false;}};
 document.getElementById('save-layout').onclick=async()=>{
  if(busy||!captureStall())return;
  const overlap=draft.stalls.some((a,i)=>draft.stalls.slice(i+1).some(b=>Math.abs(a.x-b.x)<8&&Math.abs(a.y-b.y)<8));
  if(overlap){document.getElementById('layout-error').textContent='Stalls overlap. Move them apart before saving.';return;}
  busy=true;document.getElementById('save-layout').disabled=true;
  try{
   const fresh=await backend.saveLayout(draft.details,draft.stalls.map(layoutFields),draft.revision);
   if(!fresh){draft=null;view='event';panel('Layout saved.','Your layout was saved, but the latest view could not load. Reload this page before editing again.');return;}
   draft=null;renderLayout();notify('Layout saved. Your invited vendors will see the updated map.');
  }catch(err){document.getElementById('layout-error').textContent=err.message;}finally{busy=false;const b=document.getElementById('save-layout');if(b)b.disabled=backend.event().is_open;}
 };
}
function captureStall(){
 const form=document.getElementById('stall-editor'),s=draft?.stalls.find(x=>x.id===editId);
 if(!form||!s||s.locked)return true;
 if(!form.reportValidity())return false;
 const data=Object.fromEntries(new FormData(form));for(const k of ['price','width_ft','depth_ft','x','y'])data[k]=Number(data[k]);data.power=form.elements.power.checked;Object.assign(s,data);return true;
}
window.addEventListener('beforeunload',e=>{if(draft){e.preventDefault();e.returnValue='';}});

dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
for(const [id,page] of [['event','event'],['map','vendor'],['booking','booking'],['organiser','admin'],['layout','layout']])document.getElementById(id+'-button').onclick=()=>navigate(page);
document.getElementById('sign-out').onclick=async()=>{if(busy)return;draft=null;await backend.client.auth.signOut({scope:'local'});dialog.close();showLogin();notify('Signed out on this browser.');};
(async()=>{try{backend=window.createTrialBackend(window.STALLSLOT_CONFIG);backend.client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){draft=null;dialog.close();showLogin('Your session has ended. Sign in to continue.');}});const {data:{session}}=await backend.client.auth.getSession();if(session)await startSession();else showLogin();}catch{panel('The trial is <em>getting ready.</em>','The private booking workspace is not connected yet. No requests can be submitted here until setup is complete.');main.insertAdjacentHTML('beforeend','<a class="small-button" href="/">Explore the public demo ↗</a>');}})();
